cd "$(mktemp -d)" && cat > w.c <<'EOF'
#include <curses.h>
#include <signal.h>
#include <stdio.h>
#include <unistd.h>

static void report(const char *when) {
	struct sigaction sa;
	sigaction(SIGWINCH, NULL, &sa);
	fprintf(stderr, "%-28s handler=%s\n", when,
		sa.sa_handler == SIG_DFL ? "SIG_DFL" :
		sa.sa_handler == SIG_IGN ? "SIG_IGN" : "installed");
}

int main(void) {
	struct sigaction old, curses_had;
	fprintf(stderr, "ncurses %s\n", curses_version());
	sigaction(SIGWINCH, NULL, &old);
	report("before any initscr");
	initscr();
	report("after 1st initscr");
	sigaction(SIGWINCH, NULL, &curses_had);
	endwin();
	report("after endwin");
	sigaction(SIGWINCH, &old, NULL);
	report("after restoring old");
	initscr();
	report("after 2nd initscr");
	endwin();
	sigaction(SIGWINCH, &curses_had, NULL);
	report("after re-installing saved");
	return 0;
}
EOF
gcc -o w w.c -lncurses 2>&1 | head -3
script -qec ./w /dev/null 2>&1 | tr -d '\r' | grep -v '^$'

d=$(mktemp -d); cd "$d" && cat > r.c <<'EOF'
#include <curses.h>
#include <signal.h>
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
	struct sigaction old, curses_had;
	FILE *log = fopen("log.txt", "w");
	int c, n;

	sigaction(SIGWINCH, NULL, &old);
	initscr();
	sigaction(SIGWINCH, NULL, &curses_had);	/* what curses installed */
	endwin();
	sigaction(SIGWINCH, &old, NULL);	/* the #152 give-up path */

	initscr();				/* the retry #154 wants */
	if (argc > 1 && strcmp(argv[1], "reinstall") == 0)
		sigaction(SIGWINCH, &curses_had, NULL);
	cbreak(); noecho(); keypad(stdscr, TRUE);
	mvprintw(0, 0, "ready: %s", argc > 1 ? argv[1] : "plain");
	refresh();
	for (n = 0; n < 3; n++) {
		c = getch();
		fprintf(log, "got %d %s\n", c,
			c == KEY_RESIZE ? "KEY_RESIZE" : "other");
		fflush(log);
	}
	endwin();
	fclose(log);
	return 0;
}
EOF
gcc -o r r.c -lncurses 2>&1 | head -3
for arm in plain reinstall; do
  tmux -f /dev/null -L sst154 new-session -d -x 90 -y 30 -s $arm "cd $d && ./r $arm; sleep 5"
  sleep 1
  tmux -f /dev/null -L sst154 resize-window -t $arm -x 80 -y 26
  sleep 1
  echo "=== $arm ==="; cat "$d/log.txt" 2>/dev/null || echo "(no log)"
  tmux -f /dev/null -L sst154 kill-session -t $arm 2>/dev/null
  mv "$d/log.txt" "$d/log-$arm.txt" 2>/dev/null
done
tmux -f /dev/null -L sst154 kill-server 2>/dev/null; echo done

