input.command:
d=$(mktemp -d); cd "$d" && cat > s.c <<'EOF'
#include <curses.h>
#include <signal.h>
#include <stdio.h>
int main(void) {
	struct sigaction old, cw;
	FILE *log = fopen("log.txt", "w");
	sigaction(SIGWINCH, NULL, &old);
	initscr();
	sigaction(SIGWINCH, NULL, &cw);
	fprintf(log, "1st initscr: LINES=%d COLS=%d\n", LINES, COLS);
	endwin();
	sigaction(SIGWINCH, &old, NULL);
	fflush(log);
	sleep(3);			/* resized during this */
	initscr();
	sigaction(SIGWINCH, &cw, NULL);
	fprintf(log, "2nd initscr: LINES=%d COLS=%d\n", LINES, COLS);
	resize_term(0, 0);
	fprintf(log, "after resize_term(0,0): LINES=%d COLS=%d\n", LINES, COLS);
	endwin();
	fclose(log);
	return 0;
}
EOF
gcc -o s s.c -lncurses 2>&1|head -3
tmux -f /dev/null -L sst154c new-session -d -x 70 -y 20 -s t "cd $d && ./s; sleep 3"
sleep 1; tmux -f /dev/null -L sst154c resize-window -t t -x 100 -y 30; sleep 4
cat "$d/log.txt"; tmux -f /dev/null -L sst154c kill-server 2>/dev/null

d=/tmp/tmp.ek32EjXObn; cd "$d" && cat > s2.c <<'EOF'
#include <curses.h>
#include <signal.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/ioctl.h>
int main(void) {
	struct sigaction old, cw;
	struct winsize ws;
	FILE *log = fopen("log.txt", "w");
	sigaction(SIGWINCH, NULL, &old);
	initscr();
	sigaction(SIGWINCH, NULL, &cw);
	fprintf(log, "1st initscr:        LINES=%d COLS=%d\n", LINES, COLS);
	endwin();
	sigaction(SIGWINCH, &old, NULL);
	fflush(log);
	sleep(3);				/* resized during this */
	initscr();
	fprintf(log, "2nd initscr:        LINES=%d COLS=%d\n", LINES, COLS);
	fprintf(log, "is_term_resized:    %d\n", is_term_resized(LINES, COLS));
	sigaction(SIGWINCH, &cw, NULL);
	ioctl(fileno(stdout), TIOCGWINSZ, &ws);
	fprintf(log, "ioctl says:         rows=%d cols=%d\n", ws.ws_row, ws.ws_col);
	resize_term(ws.ws_row, ws.ws_col);
	fprintf(log, "after resize_term:  LINES=%d COLS=%d\n", LINES, COLS);
	endwin();
	fclose(log);
	return 0;
}
EOF
gcc -o s2 s2.c -lncurses 2>&1|head -3
tmux -f /dev/null -L sst154d new-session -d -x 70 -y 20 -s t "cd $d && ./s2; sleep 3"
sleep 1; tmux -f /dev/null -L sst154d resize-window -t t -x 100 -y 30; sleep 4
cat "$d/log.txt"; tmux -f /dev/null -L sst154d kill-server 2>/dev/null

