/* The terminal size the panels were last turned down at, or 0 if they
 * have not been turned down for size. */
static int refusedlines, refusedcols;

/* Whether the environment has pinned the terminal size.
 *
 * The rule is ncurses' own, from _nc_getenv_num: the variable counts
 * only where it parses whole to a number above zero, so an exported
 * LINES=, LINES=0 and LINES=abc are all ignored and the terminal is
 * used. Testing merely that the variable is set would be stricter than
 * ncurses and would stand the panels down where nothing was pinned.
 *
 * Measured against ncurses 6.6.20251231 in a pane grown from 100x30 to
 * 110x34: with LINES=20 COLUMNS=70 the size stays 20x70 and
 * is_term_resized() reports no change however far the pane moves; with
 * any of the three ignored forms it follows the pane to 34x110.
 *
 * Both places that reason about size have to ask this, and for the same
 * reason: where it is TRUE, the size the game runs on cannot change. */
static int size_pinned(void) {
	static const char *const names[] = { "LINES", "COLUMNS" };
	const char *v;
	char *end;
	long n;
	size_t i;

	for (i = 0; i < sizeof names / sizeof names[0]; i++) {
		v = getenv(names[i]);
		if (v == NULL || *v == '\0') continue;
		n = strtol(v, &end, 10);
		if (*end == '\0' && n > 0) return TRUE;
	}
	return FALSE;
}

